CREATE DATABASE IF NOT EXISTS tienda2;

USE tienda2;

DROP TABLE IF EXISTS productos;


CREATE TABLE IF NOT EXISTS productos (
    asin VARCHAR(255) PRIMARY KEY,
    climate_pledge_friendly BOOLEAN,
    currency VARCHAR(10) NOT NULL,
    delivery VARCHAR(255),
    has_variations BOOLEAN DEFAULT FALSE,
    is_amazon_choice BOOLEAN DEFAULT FALSE,
    is_best_seller BOOLEAN DEFAULT FALSE,
    is_prime BOOLEAN DEFAULT FALSE,
    product_badge VARCHAR(255),
    product_minimum_offer_price DECIMAL(10,2),
    product_num_offers INT,
    product_num_ratings INT,
    product_original_price DECIMAL(10,2),
    product_photo TEXT,
    product_price DECIMAL(10,2) NOT NULL,
    product_star_rating  DECIMAL(10,1),
    product_title TEXT NOT NULL,
    product_url TEXT,
    sales_volume VARCHAR(255)
);


DROP TABLE IF EXISTS users;

CREATE TABLE IF NOT EXISTS users(
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(20) NOT NULL,
    nombre VARCHAR(20) NOT NULL,
    apellido VARCHAR(20) NOT NULL,
    email VARCHAR(255) NOT NULL,
    rol VARCHAR(20) NOT NULL,
    password VARCHAR(255) NOT NULL,
    refresh_token text,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE(username)
);


